mapper.select:
SELECT TNA.*,cc.bugcriid,cc.bugcrilevel,ORG.ORGNAME FROM TBL_NBSJ_BUG TNA LEFT JOIN TBL_NBSJ_BUG_CRITERION cir on TNA.BUGID=CIR.BUGID LEFT JOIN TBL_NBSJ_BUGCRITERION cc on cc.BUGCRIID=CIR.BUGCRIID LEFT JOIN TBL_ORGANIZATION ORG on ORG.ORGID=TNA.bugdepartment
1=1
${sql}
AND TNA.BUGID != #{tblNbsjBugVo.bugid} AND TNA.FATHERBUGID IS NULL
AND BUGDEPARTMENT=#{tblNbsjBugVo.orgid}
AND TNA.BUGNUMBER like concat(concat('%',#{tblNbsjBugVo.bugnumber}),'%')
AND TNA.DEFECTSNAME like concat(concat('%',#{tblNbsjBugVo.defectsname}),'%')
AND cir.BUGCRIID like concat(concat('%',#{tblNbsjBugVo.bugcriid}),'%')
AND to_char(TNA.DISCOVERTIME,'yyyy-mm-dd') >= #{tblNbsjBugVo.startDate}
AND to_char(TNA.DISCOVERTIME,'yyyy-mm-dd') <= #{tblNbsjBugVo.endDate}
ORDER BY TNA.BUGID DESC

SELECT * FROM TBL_NBSJ_BUG TNA LEFT JOIN TBL_NBSJ_BUG_CRITERION cir on TNA.BUGID=CIR.BUGID
1=1 AND TNA.FATHERBUGID=#{bugid}
ORDER BY TNA.BUGID DESC
